"""Algorithm A: Mobius normal form and twisted arithmetic.

A Mobius integer is an equivalence class of oriented integers (n, eps) under
the identification (n, +1) ~ (-n, -1).  The canonical invariant of a class is
its signed value eps * n, and the canonical representative is the one with
positive orientation.  All ring operations are performed on signed values.
"""

from __future__ import annotations

from typing import Tuple

Oriented = Tuple[int, int]  # (magnitude, orientation in {+1, -1})


def signed_value(a: Oriented) -> int:
    """Complete invariant of the Mobius class of an oriented integer."""
    magnitude, orientation = a
    if orientation not in (1, -1):
        raise ValueError("orientation must be +1 or -1")
    return orientation * magnitude


def normal_form(a: Oriented) -> Oriented:
    """Canonical representative of the class of `a`: positive orientation."""
    return (signed_value(a), 1)


def same_class(a: Oriented, b: Oriented) -> bool:
    """Decide whether two oriented integers are Mobius-identified."""
    return signed_value(a) == signed_value(b)


def deck(a: Oriented) -> Oriented:
    """The fixed-point-free deck involution of the double cover."""
    magnitude, orientation = a
    return (-magnitude, -orientation)


def mobius_add(a: Oriented, b: Oriented) -> Oriented:
    """Twisted addition, computed through the identification."""
    return normal_form((signed_value(a) + signed_value(b), 1))


def mobius_mul(a: Oriented, b: Oriented) -> Oriented:
    """Twisted multiplication; equivalently (m*n, eps*delta) on the cover."""
    return normal_form((signed_value(a) * signed_value(b), 1))


def mobius_norm(a: Oriented) -> int:
    """The radius: the circle of the band on which the class lies."""
    return abs(signed_value(a))


def orientation_of(a: Oriented) -> int:
    """The orientation character of a nonzero class, valued in {+1, -1}."""
    v = signed_value(a)
    if v == 0:
        raise ValueError("the centre of the band carries no orientation")
    return 1 if v > 0 else -1


def polar_decomposition(a: Oriented) -> Tuple[int, int]:
    """Write a nonzero class uniquely as (unit, positive radius)."""
    return (orientation_of(a), mobius_norm(a))


if __name__ == "__main__":
    x: Oriented = (3, -1)
    y: Oriented = (4, 1)
    print("signed values      :", signed_value(x), signed_value(y))
    print("normal forms       :", normal_form(x), normal_form(y))
    print("deck images        :", deck(x), deck(y))
    print("identified with deck:", same_class(x, deck(x)), same_class(y, deck(y)))
    print("sum                :", mobius_add(x, y))
    print("product            :", mobius_mul(x, y))
    print("polar of product   :", polar_decomposition(mobius_mul(x, y)))

"""Algorithm B: oriented prime factorization of a Mobius integer.

A Mobius integer is prime exactly when its radius is a rational prime, and two
Mobius integers are associates exactly when they differ by an orientation flip.
Hence the factorizations of a nonzero class x are obtained by factoring the
radius classically and then distributing orientations over the prime factors,
subject to the constraint that the product of the orientations reproduces the
orientation of x.  The multiset of radii is the same for all of them: it is the
complete invariant of the factorization.
"""

from __future__ import annotations

import itertools
from typing import Dict, List, Tuple


def factor_radius(n: int) -> Dict[int, int]:
    """Classical prime factorization of a positive integer, trial division."""
    if n < 1:
        raise ValueError("radius must be positive")
    factors: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors


def prime_multiset(n: int) -> List[int]:
    """The multiset of rational primes dividing n, with multiplicity."""
    out: List[int] = []
    for p, e in sorted(factor_radius(n).items()):
        out.extend([p] * e)
    return out


def oriented_factorizations(x: int) -> List[List[int]]:
    """
    All multisets of Mobius primes (given by signed values) whose product is x.

    Each entry is a list of signed primes; the product of the signs must equal
    the sign of x, so exactly half of the 2^Omega(N) sign patterns survive.
    """
    if x == 0:
        raise ValueError("zero has no prime factorization")
    radii = prime_multiset(abs(x))
    target_sign = 1 if x > 0 else -1
    results: List[List[int]] = []
    for signs in itertools.product((1, -1), repeat=len(radii)):
        product_sign = 1
        for s in signs:
            product_sign *= s
        if product_sign != target_sign:
            continue
        results.append([s * p for s, p in zip(signs, radii)])
    return results


def radii_invariant(factorization: List[int]) -> List[int]:
    """The multiset of radii: identical across all factorizations of x."""
    return sorted(abs(q) for q in factorization)


def divisor_count_mobius(x: int) -> int:
    """Number of divisors of x in the Mobius integers: twice the classical one."""
    n = abs(x)
    classical = 1
    for _, e in factor_radius(n).items():
        classical *= e + 1
    return 2 * classical


def render(factorization: List[int]) -> str:
    """Pretty-print a factorization in oriented notation, e.g. 2^+ * 3^-."""
    return " * ".join(f"{abs(q)}^{'+' if q > 0 else '-'}" for q in factorization)


if __name__ == "__main__":
    for x in (6, -6, 12, 30):
        facs = oriented_factorizations(x)
        print(f"x = {x}")
        for f in facs:
            print(f"    {render(f):<24} radii {radii_invariant(f)}")
        invariants = {tuple(radii_invariant(f)) for f in facs}
        print(f"    distinct radii multisets: {invariants}")
        print(f"    number of divisors in the Mobius integers: "
              f"{divisor_count_mobius(x)}")

"""Algorithm C: sheet counting and the spectral zeta function of the oriented
double O = Z[tau]/(tau^2 - 1).

The spectrum of O is a double cover of the spectrum of the integers, branched
exactly at the prime 2: two points above every odd prime, one point above 2.
Assigning the Euler factor (1 - p^-s)^-1 to each point gives

    zeta_O(s) = zeta(s)^2 * (1 - 2^-s),

whose Dirichlet coefficients are c(n) = d(n) - d(n/2), with d the divisor
function and d(n/2) read as 0 for odd n.  This module computes the sheet
counts, sieves the coefficients in O(X log X), and evaluates the series.
"""

from __future__ import annotations

import cmath
from typing import List


def sheets(p: int) -> int:
    """Points of the spectrum of the oriented double above the prime p."""
    return 1 if p == 2 else 2


def divisor_sieve(limit: int) -> List[int]:
    """d(n) for 0 <= n <= limit, by harmonic sieving: O(limit log limit)."""
    d = [0] * (limit + 1)
    for k in range(1, limit + 1):
        for multiple in range(k, limit + 1, k):
            d[multiple] += 1
    return d


def ideal_coefficients(limit: int) -> List[int]:
    """c(n) = d(n) - d(n/2) for 1 <= n <= limit (index 0 unused)."""
    d = divisor_sieve(limit)
    c = [0] * (limit + 1)
    for n in range(1, limit + 1):
        c[n] = d[n] - (d[n // 2] if n % 2 == 0 else 0)
    return c


def spectral_zeta_dirichlet(s: complex, limit: int = 200000) -> complex:
    """Truncated Dirichlet series sum_{n<=limit} c(n) n^-s (needs Re s > 1)."""
    c = ideal_coefficients(limit)
    total = 0j
    for n in range(1, limit + 1):
        if c[n]:
            total += c[n] * complex(n) ** (-s)
    return total


def spectral_zeta_euler(s: complex, prime_limit: int = 20000) -> complex:
    """Truncated Euler product over the spectrum, one factor per point."""
    sieve = [True] * (prime_limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(prime_limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, prime_limit + 1, i):
                sieve[j] = False
    result = 1 + 0j
    for p in range(2, prime_limit + 1):
        if sieve[p]:
            factor = (1 - complex(p) ** (-s)) ** (-1)
            result *= factor ** sheets(p)
    return result


def branch_factor(s: complex) -> complex:
    """The ramified Euler correction 1 - 2^-s; its zeros are 2 pi i k / log 2."""
    return 1 - complex(2) ** (-s)


def new_zero(k: int) -> complex:
    """The k-th zero contributed by the branch prime 2 (k a nonzero integer)."""
    import math
    return complex(0.0, 2 * math.pi * k / math.log(2))


if __name__ == "__main__":
    print("sheet counts   :", {p: sheets(p) for p in (2, 3, 5, 7, 11, 13)})
    print("c(1..12)       :", ideal_coefficients(12)[1:])
    for s in (2.0, 3.0, 4.0):
        d = spectral_zeta_dirichlet(complex(s), 100000).real
        e = spectral_zeta_euler(complex(s)).real
        print(f"s = {s}:  Dirichlet {d:.10f}   Euler {e:.10f}")
    import math
    print(f"zeta_O(2) exact = pi^4/48 = {math.pi ** 4 / 48:.10f}")
    for k in (1, 2, 3):
        z = new_zero(k)
        print(f"branch zero k={k}: s = {z.imag:.6f}i, "
              f"|1 - 2^-s| = {abs(branch_factor(z)):.3e}")
